(42220, 'Deuteronomy 17:15', 'Deuteronomy', 17, 15, 'ګورئ، کوم سړی چې تاسو د پاچا په توګه غوره کوئ، باید هغه څوک وي چې د څښتن له خوا غوره شوی وي. هغه باید ستاسو د قوم څخه وي. کوم پردی سړی خپل پاچا نه کړئ.', 'ګوری، کوم سری چې تاسو د پاچا په توګه غوره کوی، باید هغه چوک وی چې د چشتن له خوا غوره شوی وی. هغه باید ستاسو د قوم چخه وی. کوم پردی سری خپل پاچا نه کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_17_15.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(42221, 'Deuteronomy 17:16', 'Deuteronomy', 17, 16, 'د پاچا لښکر باید زیات اسونه ونه لري او هغه باید مصر ته خلک د دې دپاره ونه لېږي چې هلته اسونه په بیه واخلي، ځکه چې څښتن ویلي دي چې د هغه قوم دې هېڅکله هلته بېرته نه ځي.', 'د پاچا لشکر باید زیات اسونه ونه لری او هغه باید مصر ته خلک د دې دپاره ونه لېزی چې هلته اسونه په بیه واخلی، جکه چې چشتن ویلی دی چې د هغه قوم دې هېچکله هلته بېرته نه جی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_17_16.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(42222, 'Deuteronomy 17:17', 'Deuteronomy', 17, 17, 'پاچا باید ډېرې ښځې ونه لري، ځکه چې هغوی به هغه ولمسوي چې د څښتن په وړاندې بې وفا شي. په پای کې، پاچا باید د دې هڅه ونه کړي چې په زیاته اندازه سره زر او سپین زر لاسته راوړي.', 'پاچا باید دېرې شجې ونه لری، جکه چې هغوی به هغه ولمسوی چې د چشتن په وراندې بې وفا شی. په پای کې، پاچا باید د دې هچه ونه کری چې په زیاته اندازه سره زر او سپین زر لاسته راوری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_17_17.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
