(42251, 'Exodus 1:7', 'Exodus', 1, 7, 'خو د هغوی اولاده یعنې اسراییلیان د زیاتو اولادونو خاوندان شول او هغوی دومره زیات شول چې مصر ورڅخه ډک شو.', 'خو د هغوی اولاده یعنې اسراییلیان د زیاتو اولادونو خاوندان شول او هغوی دومره زیات شول چې مصر ورچخه دک شو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_1_7.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(42252, 'Exodus 1:8', 'Exodus', 1, 8, 'له ډېرو کلونو وروسته په مصر کې یو نوي پاچا قدرت تر لاسه کړ چې هغه د یوسف په اړه هېڅ معلومات نه درلود.', 'له دېرو کلونو وروسته په مصر کې یو نوی پاچا قدرت تر لاسه کر چې هغه د یوسف په اره هېچ معلومات نه درلود.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_1_8.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(42253, 'Exodus 1:9', 'Exodus', 1, 9, 'هغه مصریانو ته وویل: «د اسراییلو شمېر زمونږ په خاوره کې ډېر شوی دی او هغوی زمونږ نه ډېر قوي دي.', 'هغه مصریانو ته وویل: «د اسراییلو شمېر زمونز په خاوره کې دېر شوی دی او هغوی زمونز نه دېر قوی دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_1_9.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(42254, 'Exodus 1:10', 'Exodus', 1, 10, 'که چېرې جنګ وشي، نو کېدای شي چې هغوی زمونږ د دښمنانو سره یوځای شي او زمونږ په وړاندې وجنګیږي او د دې وطن څخه وتښتي. نو مونږ باید کومه لاره چاره وسنجوو او پرېنږدو چې د هغوی شمېر له دې څخه نور هم زیات شي.»', 'که چېرې جنګ وشی، نو کېدای شی چې هغوی زمونز د دشمنانو سره یوجای شی او زمونز په وراندې وجنګیزی او د دې وطن چخه وتشتی. نو مونز باید کومه لاره چاره وسنجوو او پرېنزدو چې د هغوی شمېر له دې چخه نور هم زیات شی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_1_10.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(42255, 'Exodus 1:11', 'Exodus', 1, 11, 'نو مصریانو په اسراییلیانو باندې مشران وټاکل، ترڅو هغوی په سختو کارونو باندې کمزوري کړي. هغوی د فیتوم او رعمسیس ښارونه چې فرعون په کې خپل ګودامونه ساتل، جوړ کړل.', 'نو مصریانو په اسراییلیانو باندې مشران وتاکل، ترچو هغوی په سختو کارونو باندې کمزوری کری. هغوی د فیتوم او رعمسیس شارونه چې فرعون په کې خپل ګودامونه ساتل، جور کرل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_1_11.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(42256, 'Exodus 1:12', 'Exodus', 1, 12, 'که څه هم د اسراییلیانو سره بد چلند کېده، خو د هغوی شمېر زیاتېده او نوره ځمکه یې هم ونیوله. له دې امله مصریانو له هغوی څخه وېره درلودله', 'که چه هم د اسراییلیانو سره بد چلند کېده، خو د هغوی شمېر زیاتېده او نوره جمکه یې هم ونیوله. له دې امله مصریانو له هغوی چخه وېره درلودله', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_1_12.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(42257, 'Exodus 1:15', 'Exodus', 1, 15, 'بیا فرعون دوه دایې ګانې راوغوښتلې چې شفره او فوعه نومېدلې او هغوی د عبرانۍ ښځو سره د اولاد د زېږولو په وخت کې مرسته کوله.', 'بیا فرعون دوه دایې ګانې راوغوشتلې چې شفره او فوعه نومېدلې او هغوی د عبرانی شجو سره د اولاد د زېزولو په وخت کې مرسته کوله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_1_15.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(42258, 'Exodus 1:16', 'Exodus', 1, 16, 'هغوی ته یې وویل: «که چېرې یوه عبرانۍ ښځه انجلۍ وزېږوي، هغه ژوندۍ پرېږدئ او که چېرې هلک وي، نو ویې وژنئ!»', 'هغوی ته یې وویل: «که چېرې یوه عبرانی شجه انجلی وزېزوی، هغه ژوندی پرېزدی او که چېرې هلک وی، نو ویې وژنی!»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_1_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(42259, 'Exodus 1:17', 'Exodus', 1, 17, 'که څه هم فرعون ورته ویلي وو، خو دا ښځې د خدای څخه وېرېدلې او هلکان یې نه وژل.', 'که چه هم فرعون ورته ویلی وو، خو دا شجې د خدای چخه وېرېدلې او هلکان یې نه وژل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_1_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
